# Monthly budget planner (budget-calculator/)
BUDGET_HTML=r"""<h2>Plan your budget</h2>
<div class="grid"><div><label for="bper">Amounts are per</label><select id="bper"><option value="month">Month</option><option value="week">Week</option><option value="year">Year</option></select></div>
<div><label class="check" style="margin-top:34px"><input type="checkbox" id="bsave"> Remember my budget on this device</label></div></div>
<h3 style="margin-top:20px">Income</h3><table id="inc" class="btab"><caption class="vh">Income sources</caption><thead><tr><th scope="col">Source</th><th scope="col">Amount ($)</th><th scope="col"><span class="vh">Remove</span></th></tr></thead><tbody></tbody></table>
<button type="button" class="alt" id="addinc">+ Add income</button>
<h3 style="margin-top:20px">Expenses</h3><table id="exp" class="btab"><caption class="vh">Expense categories</caption><thead><tr><th scope="col">Category</th><th scope="col">Type</th><th scope="col">Amount ($)</th><th scope="col"><span class="vh">Remove</span></th></tr></thead><tbody></tbody></table>
<button type="button" class="alt" id="addexp">+ Add expense</button><button type="button" class="alt" id="breset">Reset to defaults</button>
<p id="bst" aria-live="polite"></p>
<div id="bres" class="out" style="white-space:normal" aria-live="polite"></div>"""
BUDGET_CSS='.btab{table-layout:fixed}.btab td input,.btab td select{min-width:0;padding:8px;margin:0}.btab td button{padding:8px 10px;margin:0;min-height:44px;min-width:44px;justify-content:center}#exp th:nth-child(2){width:28%}#exp th:nth-child(3),#inc th:nth-child(2){width:28%}.btab th:last-child{width:56px}.bars{list-style:none;padding:0;margin:8px 0 0}.bars li{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.4fr);gap:10px;align-items:center;margin:6px 0;font-size:.95rem}.bbar{height:14px;border-radius:7px;background:#e6e4f7;overflow:hidden}.bbar span{display:block;height:100%;background:linear-gradient(90deg,#5a4ce8,#3324ad);border-radius:7px}.bars .bt{grid-column:1/-1;margin-top:-4px;color:var(--muted);font-size:.85rem}.bneg{color:#9b1c1c;font-weight:700}.bpos{color:#0b6b45;font-weight:700}'
BUDGET_JS=r"""const $=id=>document.getElementById(id),KEY='gwb-budget',F={month:1,week:12/52,year:12},PL={month:'month',week:'week',year:'year'};
const DEF={per:'month',inc:[['Salary (after tax)',4000]],exp:[['Rent / mortgage','need',1400],['Utilities','need',180],['Groceries','need',450],['Transport','need',250],['Insurance','need',200],['Debt payments','need',300],['Subscriptions','want',60],['Savings','save',400],['Other','want',250]]};
const m=x=>(x<0?'-$':'$')+Math.abs(x).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}),pc=x=>(x*100).toFixed(1)+'%',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let uid=0,per='month';
function rowBtn(r,lab){const b=document.createElement('button');b.type='button';b.className='alt';b.textContent='\u00d7';const nm=r.querySelector('input');const upd=()=>b.setAttribute('aria-label','Remove '+(nm.value||lab));upd();nm.addEventListener('input',upd);b.onclick=()=>{const tb=r.parentNode;r.remove();calc();const f=tb.querySelector('input');(f||$(tb.closest('table').id==='inc'?'addinc':'addexp')).focus()};return b}
function addInc(n='',a=''){const r=$('inc').tBodies[0].insertRow(),i=++uid;r.innerHTML=`<td><input id="in${i}" aria-label="Income source name" maxlength="60"></td><td><input id="ia${i}" type="number" min="0" step="any" inputmode="decimal" aria-label="Income amount"></td><td></td>`;r.cells[0].firstChild.value=n;r.cells[1].firstChild.value=a;r.cells[2].append(rowBtn(r,'income'));return r}
function addExp(n='',t='need',a=''){const r=$('exp').tBodies[0].insertRow(),i=++uid;r.innerHTML=`<td><input id="en${i}" aria-label="Expense category name" maxlength="60"></td><td><select id="et${i}" aria-label="Expense type"><option value="need">Need</option><option value="want">Want</option><option value="save">Savings</option></select></td><td><input id="ea${i}" type="number" min="0" step="any" inputmode="decimal" aria-label="Expense amount"></td><td></td>`;r.cells[0].firstChild.value=n;r.cells[1].firstChild.value=t;r.cells[2].firstChild.value=a;r.cells[3].append(rowBtn(r,'expense'));return r}
function load(d){$('inc').tBodies[0].innerHTML='';$('exp').tBodies[0].innerHTML='';per=d.per||'month';$('bper').value=per;(d.inc||[]).forEach(x=>addInc(x[0],x[1]));(d.exp||[]).forEach(x=>addExp(x[0],x[1],x[2]))}
/* read & validate: returns null if any field invalid */
function read(){let bad=false;const num=(el,lab)=>{const v=GWB.num(el,{label:lab,min:0,max:1e9,optional:true,def:0});if(v===null)bad=true;return v||0};
const inc=[...$('inc').tBodies[0].rows].map((r,i)=>{const[n,a]=r.querySelectorAll('input');return{name:n.value.trim()||'Income '+(i+1),amt:num(a,'Income amount')}});
const exp=[...$('exp').tBodies[0].rows].map((r,i)=>{const n=r.querySelector('input'),t=r.querySelector('select'),a=r.querySelectorAll('input')[1];return{name:n.value.trim()||'Expense '+(i+1),type:t.value,amt:num(a,'Expense amount')}});
return bad?null:{per,inc,exp}}
window.budgetCalc=d=>{const ti=d.inc.reduce((s,x)=>s+x.amt,0),te=d.exp.reduce((s,x)=>s+x.amt,0),by={need:0,want:0,save:0};d.exp.forEach(x=>by[x.type]+=x.amt);
return{ti,te,left:ti-te,share:x=>ti>0?x/ti:null,by,rule:[['Needs (50%)',by.need,.5],['Wants (30%)',by.want,.3],['Savings & debt extra (20%)',by.save,.2]].map(([k,v,t])=>({k,v,t,target:ti*t,pct:ti>0?v/ti:null}))}};
const TYPE={need:'Need',want:'Want',save:'Savings'};
function calc(){const d=read();if(!d){$('bres').innerHTML='<p class="gwb-bad">Fix the highlighted amounts to see your budget.</p>';window.__budget=null;return}
const r=budgetCalc(d),P=PL[per],sh=x=>r.share(x)===null?'n/a':pc(r.share(x));window.__budget={d,r};
const cats=d.exp.map(x=>`<tr><th scope="row">${esc(x.name)}</th><td>${TYPE[x.type]}</td><td>${m(x.amt)}</td><td>${sh(x.amt)}</td></tr>`).join('');
const mx=Math.max(1,r.ti,...d.exp.map(x=>x.amt));
const bars=d.exp.map(x=>`<li><span>${esc(x.name)}</span><span class="bbar" aria-hidden="true"><span style="width:${Math.min(100,x.amt/mx*100).toFixed(1)}%"></span></span><span class="bt">${m(x.amt)} per ${P}${r.ti>0?' · '+pc(x.amt/r.ti)+' of income':''}</span></li>`).join('');
$('bres').innerHTML=(r.ti<=0?'<p class="gwb-bad">Add at least one income amount to see percentages and the 50/30/20 comparison.</p>':'')+
`<table id="bsum"><caption class="vh">Budget summary per ${P}</caption><tr><th scope="row">Total income</th><td>${m(r.ti)}</td></tr><tr><th scope="row">Total expenses</th><td>${m(r.te)}</td></tr><tr><th scope="row">${r.left>=0?'Remaining':'Shortfall'}</th><td class="${r.left>=0?'bpos':'bneg'}">${m(Math.abs(r.left))}</td></tr></table>`+
`<p>${r.left>=0?`You have <strong>${m(r.left)}</strong> left over each ${P}.`:`You are spending <strong>${m(-r.left)}</strong> more than you earn each ${P}.`}</p>`+
`<h3>Expenses by category</h3><table id="bcat"><caption class="vh">Expenses by category, per ${P}</caption><tr><th scope="col">Category</th><th scope="col">Type</th><th scope="col">Amount</th><th scope="col">% of income</th></tr>${cats}</table>`+
`<h3>Spending chart</h3><ul class="bars" aria-label="Spending by category">${bars}</ul>`+
`<h3>50/30/20 comparison</h3><table id="brule"><caption class="vh">50/30/20 rule comparison</caption><tr><th scope="col">Group</th><th scope="col">Yours</th><th scope="col">% of income</th><th scope="col">Target</th></tr>${r.rule.map(x=>`<tr><th scope="row">${x.k}</th><td>${m(x.v)}</td><td>${x.pct===null?'n/a':pc(x.pct)}</td><td>${m(x.target)}</td></tr>`).join('')}</table>`+
`<p class="hsmall">The 50/30/20 rule is a common guideline: about 50% of take-home pay for needs, 30% for wants and 20% for savings and extra debt payments. It's a starting point, not financial advice.</p>`;save()}
function snap(){const n=x=>Math.round((+x||0)*100)/100;return{per,inc:[...$('inc').tBodies[0].rows].map(r=>{const[a,b]=r.querySelectorAll('input');return[a.value,b.value]}),exp:[...$('exp').tBodies[0].rows].map(r=>{const i=r.querySelectorAll('input');return[i[0].value,r.querySelector('select').value,i[1].value]})}}
function save(){try{if($('bsave').checked)localStorage.setItem(KEY,JSON.stringify(snap()))}catch(_){GWB.status('bst','Your browser blocked saving, so the budget will not be remembered. Everything else still works.','error')}}
$('bsave').onchange=()=>{try{if($('bsave').checked){save();GWB.status('bst','Saved on this device only. Nothing is uploaded.')}else{localStorage.removeItem(KEY);GWB.status('bst','Saved budget removed from this device.')}}catch(_){GWB.status('bst','Your browser blocked saving.','error')}};
$('bper').onchange=()=>{const np=$('bper').value,k=F[np]/F[per];document.querySelectorAll('#inc input[type=number],#exp input[type=number]').forEach(i=>{if(i.value.trim()!==''&&Number.isFinite(+i.value))i.value=Math.round(+i.value*k*100)/100});per=np;calc()};
$('addinc').onclick=()=>{addInc().querySelector('input').focus();calc()};$('addexp').onclick=()=>{addExp().querySelector('input').focus();calc()};
$('breset').onclick=()=>{load(DEF);calc();GWB.status('bst','Reset to the default categories.')};
$('tool').addEventListener('input',e=>{if(e.target.closest('#inc,#exp'))calc()});$('tool').addEventListener('change',e=>{if(e.target.closest('#exp')&&e.target.tagName==='SELECT')calc()});
let init=DEF;try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&Array.isArray(s.inc)&&Array.isArray(s.exp)){init=s;$('bsave').checked=true}}catch(_){}
load(init);calc();"""
BUDGET_SPEC=r"""window.GWB_EXPORT={slug:'budget',title:'Monthly Budget Plan',get(){const B=window.__budget;if(!B||GWB.hasErrors())return null;const{d,r}=B,P={month:'Monthly',week:'Weekly',year:'Annual'}[d.per],m=x=>(x<0?'-$':'$')+Math.abs(x).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}),pc=x=>x===null?'n/a':(x*100).toFixed(1)+'%';
return{title:P+' Budget Plan',inputs:[['Amounts are per',d.per]],tables:[{name:'Income',head:['Source','Amount'],rows:d.inc.map(x=>[x.name,m(x.amt)])},{name:'Expenses',head:['Category','Type','Amount','% of income'],rows:d.exp.map(x=>[x.name,{need:'Need',want:'Want',save:'Savings'}[x.type],m(x.amt),pc(r.share(x.amt))])},
{name:'Summary',head:['Item','Amount'],rows:[['Total income',m(r.ti)],['Total expenses',m(r.te)],[r.left>=0?'Remaining':'Shortfall',m(Math.abs(r.left))]]},{name:'50/30/20 comparison',head:['Group','Yours','% of income','Target'],rows:r.rule.map(x=>[x.k,m(x.v),pc(x.pct),m(x.target)])}],
notes:['The 50/30/20 rule is a general guideline, not financial advice.','Amounts as entered; GWB does not store or upload your budget.']}}};"""
